            return inicio; // Encontramos el valor, devolvemos el nodo
        } else if (inicio->valor < valorBuscar) {
            inicio = inicio->der; // Buscamos en el subárbol derecho
        } else {
            inicio = inicio->izq; // Buscamos en el subárbol izquierdo
        }
    }
    return NULL; // No encontramos el valor en el árbol
