Here is an example of how you can implement session management using Google OAuth in a React application using classes instead of effects and Material Design:
```
import React, { Component } from 'react';
import { GoogleAuthProvider, googleAuth } from 'react-google-login';
import { Container, Grid, Button } from '@material-ui/core';
import config from './config';

class Auth extends Component {
  constructor(props) {
    super(props);
    this.state = {
      user: null,
      accessToken: null,
      refreshToken: null,
    };
  }

  handleLogin = () => {
    const provider = new GoogleAuthProvider();
    googleAuth(provider, 'YOUR_CLIENT_ID')
      .then((googleUser) => {
        const { accessToken, refreshToken } = googleUser.getAuthResponse();
        this.setState({
          user: googleUser.getProfile(),
          accessToken,
          refreshToken,
        });
      })
      .catch((error) => {
        console.error(error);
      });
  };

  handleLogout = () => {
    this.setState({
      user: null,
      accessToken: null,
      refreshToken: null,
    });
  };

  render() {
    const { user } = this.state;
    return (
      <Container maxWidth="sm">
        <Grid container spacing={2}>
          {user ? (
            <Grid item xs={12}>
              <Button
                variant="contained"
                color="primary"
                onClick={this.handleLogout}
              >
                Logout
              </Button>
            </Grid>
          ) : (
            <Grid item xs={12}>
              <Button
                variant="contained"
                color="primary"
                onClick={this.handleLogin}
              >
                Login with Google
              </Button>
            </Grid>
          )}
        </Grid>
      </Container>
    );
  }
}

export default Auth;
```
